11	/// Build an [`Upstream`] pointing at `url` with `headers`, all per-uplink
12	/// tuning knobs at their verdaccio defaults.
13	fn upstream(url: String, headers: HeaderMap) -> Upstream {
14	    Upstream::new("npmjs", &UplinkConfig::with_defaults(url, headers))
15	}
