38	#[tokio::test]
39	async fn serves_scoped_packument_from_storage() {
40	    let storage = common::build_storage();
41	    let app = router(static_config(storage.path().to_path_buf()));
42	
43	    let response =
44	        app.oneshot(Request::get("/@foo/no-deps").body(Body::empty()).unwrap()).await.unwrap();
45	    assert_eq!(response.status(), StatusCode::OK);
46	
47	    let doc: Value = serde_json::from_slice(&body_bytes(response.into_body()).await).unwrap();
48	    assert_eq!(doc["name"], "@foo/no-deps");
49	    assert_eq!(doc["dist-tags"]["latest"], "1.0.0");
50	
51	    // The on-disk packument has a Verdaccio-form tarball URL —
52	    // `http://localhost:4873/@foo/no-deps/-/@foo/no-deps-1.0.0.tgz`.
53	    // After our rewrite the client should see the npm-spec form
54	    // pointed at our `public_url`.
55	    assert_eq!(
56	        doc["versions"]["1.0.0"]["dist"]["tarball"],
57	        format!("{PUBLIC_URL}/@foo/no-deps/-/no-deps-1.0.0.tgz"),
58	    );
59	    // Other fields (integrity, shasum, name, version) should pass
60	    // through untouched.
61	    assert_eq!(
62	        doc["versions"]["1.0.0"]["dist"]["shasum"],
63	        "a1c3e0c08af5ec17f150b8b9f067bead3d64e472",
64	    );
65	    assert!(doc["versions"]["1.0.0"]["dist"]["integrity"].as_str().unwrap().starts_with("sha512-"));
66	}
