}", "newString": "/// Extract the basename from a tarball URL, stripping any query string
/// (`?...`) or URL fragment (`#...`). Returns the last non-empty path
/// segment, or `None` when the URL ends in a trailing slash or has no
/// usable segment.
///
/// This preserves whatever filename the upstream chose — including
/// non-canonical names that don't follow the `<name>-<version>.tgz`
/// convention — so the route pnpr serves matches the one the client's
/// resolver derived from the same `dist.tarball`.
///
/// ```ignore
/// tarball_basename("https://r/foo/-/foo-1.0.0.tgz")       // Some("foo-1.0.0.tgz")
/// tarball_basename("https://r/foo/-/foo-1.0.0.tgz?sig=x") // Some("foo-1.0.0.tgz")
/// tarball_basename("https://r/foo/-/foo-1.0.0.tgz#frag")  // Some("foo-1.0.0.tgz")
/// tarball_basename("foo-1.0.0.tgz")                        // Some("foo-1.0.0.tgz")
/// tarball_basename("https://r/foo/")                        // None
/// ```
pub fn tarball_basename(url: &str) -> Option<&str> {
    // The path ends at the first `?` (query) or `#` (fragment); the
    // basename is the last `/`-separated segment of what remains.
    let path = url.split(['?', '#']).next().unwrap_or(url);
    let segment = path.rsplit('/').next().unwrap_or(path);
    (!segment.is_empty()).then_some(segment)
}

/// Rewrite every `dist.tarball` in `value` to a URL served by *this*
/// registry instead of whatever URL the source put there. Each new URL
/// keeps the upstream tarball's basename (see [`tarball_basename`]) so a
/// client resolving the same `dist.tarball` derives the identical route,
/// falling back to the conventional `<name>-<version>.tgz` only when the
/// upstream URL yields no usable basename.
///
/// The version-manifest endpoint calls [`extract_version_manifest`],
/// which binds the rewrite to its resolved `versions` map key directly.
pub fn rewrite_tarball_urls(value: &mut Value, pkg: &PackageName, public_url: &str) {
    let public_url = public_url.trim_end_matches('/');
    if let Some(versions) = value.get_mut("versions").and_then(Value::as_object_mut) {
        for (version, manifest) in versions {
            rewrite_dist_tarball(manifest, pkg, version, public_url);
        }
    }
}

/// The public tarball route filename pnpr serves for a single version
/// manifest: the upstream `dist.tarball` basename when it has one,
/// otherwise the conventional `<name>-<version>.tgz` built from the
/// manifest's declared `version` field (falling back to the `versions`
/// map key `version` when the manifest omits it).
///
/// Returns `None` when the manifest has no `dist.tarball` string — there
/// is no tarball to route to, so [`rewrite_dist_tarball`] leaves it
/// untouched and the server treats it as a non-match. Both the rewrite
/// and the server's route resolution go through this one function so the
/// URL a client is handed and the route the server accepts can't drift.
pub(crate) fn version_tarball_filename(
    manifest: &Value,
    pkg: &PackageName,
    version: &str,
) -> Option<String> {
    let tarball = manifest.get("dist").and_then(|dist| dist.get("tarball")).and_then(Value::as_str)?;
    Some(match tarball_basename(tarball) {
        Some(basename) => basename.to_string(),
        None => {
            let version = manifest.get("version").and_then(Value::as_str).unwrap_or(version);
            pkg.tarball_name_for_version(version)
        }
    })
}

fn rewrite_dist_tarball(value: &mut Value, pkg: &PackageName, version: &str, public_url: &str) {
    let Some(filename) = version_tarball_filename(value, pkg, version) else {
        return;
    };
    let rewritten = Value::String(format!("{public_url}/{}/-/{filename}", pkg.as_str()));
    if let Some(dist) = value.get_mut("dist").and_then(Value::as_object_mut) {
        dist.insert("tarball".to_string(), rewritten);
    }
