}", "newString": "/// Resolve which packument version a tarball request names by matching
/// the requested `filename` against each version's public tarball route
/// (see [`version_tarball_filename`]) — the exact inverse of the rewrite
/// pnpr applies to `dist.tarball`. Returns the declaring version string
/// and its SRI integrity, so the fetch, cache key, and verification are
/// all bound to the version that actually declared the basename rather
/// than to whatever version the filename's text happens to encode.
///
/// * `Ok(None)` — no version routes to this basename (a 404).
/// * `Err(AmbiguousTarball)` — two versions route to the same basename;
///   the proxy can't pick one, so it refuses with a 502 (the caller must
///   not contact the upstream tarball endpoint).
fn resolve_tarball_version(
    packument: &[u8],
    name: &PackageName,
    filename: &str,
) -> Result<Option<(String, Integrity)>, RegistryError> {
    let packument: Value = serde_json::from_slice(packument)?;
    let Some(versions) = packument.get("versions").and_then(Value::as_object) else {
        return Ok(None);
    };
    let mut matched: Option<(&String, &Value)> = None;
    for (version, manifest) in versions {
        if version_tarball_filename(manifest, name, version).as_deref() != Some(filename) {
            continue;
        }
        if let Some((first, _)) = matched {
            return Err(RegistryError::AmbiguousTarball {
                package: name.as_str().to_string(),
                filename: filename.to_string(),
                reason: format!(
                    "versions {first:?} and {version:?} both declare this tarball basename"
                ),
            });
        }
        matched = Some((version, manifest));
    }
    let Some((version, manifest)) = matched else {
        return Ok(None);
    };
    let declared = manifest
        .get("dist")
        .and_then(|dist| dist.get("integrity"))
        .and_then(Value::as_str)
        .ok_or_else(|| {
            tarball_integrity_error(
                name,
                filename,
                format!("packument has no dist.integrity for version {version:?}"),
            )
        })?;
    let integrity = streaming::parse_integrity(declared).map_err(|err| {
        tarball_integrity_error(name, filename, format!("malformed dist.integrity: {err}"))
    })?;
    Ok(Some((version.clone(), integrity)))
