/// Whether `filename` is safe to use as a single on-disk path segment for
/// a tarball. Tarball basenames are taken verbatim from an upstream
/// `dist.tarball` URL (see [`crate::upstream::tarball_basename`]), so a
/// request that reaches the store must first be checked for traversal or
/// separators — a crafted packument must not be able to steer a read or
/// write outside the package directory.
pub fn is_safe_tarball_filename(filename: &str) -> bool {
    is_safe_segment(filename)
}

fn is_safe_segment(segment: &str) -> bool {
    !segment.is_empty()
        && !segment.starts_with('.')
        && !segment.contains('/')
        && !segment.contains('\\')
        && !segment.contains('\0')
        && segment != ".."
}

