+fn tarball_basename(url: &str) -> Option<&str> {
+    let path = url.split(['?', '#']).next().unwrap_or(url);
+    let segment = path.rsplit('/').next().unwrap_or(path);
+    (!segment.is_empty()).then_some(segment)
+}
+fn main() {
+    let cases = [
+        ("https://r/foo/-/foo-1.0.0.tgz", Some("foo-1.0.0.tgz")),
+        ("https://r/foo/-/foo-1.0.0.tgz?sig=x", Some("foo-1.0.0.tgz")),
+        ("https://r/foo/-/foo-1.0.0.tgz#frag", Some("foo-1.0.0.tgz")),
+        ("foo-1.0.0.tgz", Some("foo-1.0.0.tgz")),
+        ("https://r/foo/", None),
+        ("https://cdn.example.com/foo/-/foo-1.0.0.tgz?sig=abc&exp=123", Some("foo-1.0.0.tgz")),
+        ("http://localhost:4873/@foo/no-deps/-/@foo/no-deps-1.0.0.tgz", Some("no-deps-1.0.0.tgz")),
+        ("https://r/foo/-/foo-1.0.0.tgz#frag?late", Some("foo-1.0.0.tgz")),
+    ];
+    let mut ok = true;
+    for (url, want) in cases {
+        let got = tarball_basename(url);
+        let pass = got == want;
+        ok &= pass;
+        println!("{} {:?} -> {:?} (want {:?})", if pass {"OK "} else {"BAD"}, url, got, want);
+    }
